import { LandingScript } from "@/components/shared/LandingScript";

// The full designed MediFlow marketing landing page. Its markup + CSS are
// stored as Base64 below and decoded on the server at request time — not
// because the content is secret, but because it's plain HTML/CSS/JS
// (curly quotes, an emoji, code-comment backticks) that would otherwise
// need fragile escaping to live safely inside a TypeScript template
// literal. Base64 sidesteps that entirely: it can only ever contain
// letters, numbers, +, /, and =, so there is nothing here for the
// TypeScript/JSX parser to misread.
//
// React's dangerouslySetInnerHTML never executes injected <script> tags
// (this is standard browser behavviour for anything inserted via
// innerHTML, not a Next.js quirk) — so the interactive part (chat demo,
// doctor carousel, phone tilt, etc.) is handled separately by
// <LandingScript>, a tiny client component that creates a real <script>
// element and appends it after the markup above has mounted.
const LANDING_HTML_B64 =
  "";

const LANDING_JS_B64 =
  "";

function decodeBase64Utf8(b64: string): string {
  return Buffer.from(b64, "base64").toString("utf-8");
}

export default function RootPage() {
  const html = decodeBase64Utf8(LANDING_HTML_B64);
  const script = decodeBase64Utf8(LANDING_JS_B64);

  return (
    <>
      <div dangerouslySetInnerHTML={{ __html: html }} />
      <LandingScript code={script} />
    </>
  );
}
